const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    var reyk = ee.Geometry.Point([-21.9426, 64.1466]).buffer(3000);
    var grind = ee.Geometry.Point([-22.4338, 63.8424]).buffer(3000);
    var aoi = reyk.union(grind);
    var dayStart = '2024-11-21';
    var dayEnd = '2024-11-22';
    var monthStart = '2024-11-01';
    var monthEnd = '2024-12-01';
    var scale = 1000;

    function tryLoadCollection(id, start, end) {
      try {
        var col = ee.ImageCollection(id).filterDate(start, end).filterBounds(aoi);
        var size = col.size().getInfo();
        return { ok: true, col: col, size: size, id: id };
      } catch (e) {
        return { ok: false, error: String(e), id: id };
      }
    }

    function chooseBand(col) {
      var first = ee.Image(col.first());
      var names = first.bandNames().getInfo();
      var preferred = [
        'DNB_BRDF-Corrected_NTL',
        'Gap_Filled_DNB_BRDF-Corrected_NTL',
        'Gap_Filled_DNB_BRDF_Corrected_NTL',
        'avg_rad',
        'DNB_At_Sensor_Radiance_500m'
      ];
      for (var i = 0; i < preferred.length; i++) {
        if (names.indexOf(preferred[i]) !== -1) return preferred[i];
      }
      return null;
    }

    function cleanNTL(img, band) {
      var b = img.select([band]);
      var cleaned = b.updateMask(b.gte(0)).updateMask(b.lt(1e5));
      return cleaned.rename(band);
    }

    function composite(col, band) {
      return col.select([band]).median();
    }

    function stats(img, band, region) {
      var valid = img.select([band]).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get(band);
      var mean = img.select([band]).reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get(band);
      var total = ee.Image(1).rename('ones').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: region,
        scale: scale,
        maxPixels: 1e9
      }).get('ones');
      return {
        valid: ee.Number(valid),
        mean: ee.Number(mean),
        total: ee.Number(total)
      };
    }

    // 2. Data Acquisition & Check (with fallbacks)
    var chosen = null;
    var attempts = [];

    // Try daily Black Marble
    var daily1 = tryLoadCollection('NOAA/VIIRS/001/VNP46A2', dayStart, dayEnd);
    attempts.push(daily1);
    var daily2 = tryLoadCollection('NASA/VIIRS/001/VNP46A2', dayStart, dayEnd);
    attempts.push(daily2);

    // Fallback monthly Black Marble
    var monthly1 = tryLoadCollection('NOAA/VIIRS/001/VNP46A3', monthStart, monthEnd);
    attempts.push(monthly1);

    // Fallback monthly VIIRS DNB (NOAA)
    var monthly2 = tryLoadCollection('NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG', monthStart, monthEnd);
    attempts.push(monthly2);

    // Pick first with size > 0
    for (var k = 0; k < attempts.length; k++) {
      if (attempts[k].ok && attempts[k].size > 0) {
        chosen = attempts[k];
        break;
      }
    }

    if (!chosen) {
      // Log concise attempt results
      var lines = attempts.slice(0, 4).map(function(a) {
        if (!a.ok) return a.id + ': error';
        return a.id + ': ' + a.size;
      });
      console.log('Collections (sizes): ' + lines.join(' | '));
      console.log('No images found for date/location.');
      console.log('C1');
      return;
    }

    var band = chooseBand(chosen.col);
    if (!band) {
      console.log('Dataset: ' + chosen.id + ' | Images: ' + chosen.size);
      console.log('No suitable band found.');
      console.log('D');
      return;
    }

    var comp = composite(chosen.col, band);
    comp = cleanNTL(comp, band);

    // 3. Processing and Validation
    var reykStats = stats(comp, band, reyk);
    var grindStats = stats(comp, band, grind);

    var reykValid = reykStats.valid.getInfo();
    var reykTotal = reykStats.total.getInfo();
    var reykMean = reykStats.mean.getInfo();

    var grindValid = grindStats.valid.getInfo();
    var grindTotal = grindStats.total.getInfo();
    var grindMean = grindStats.mean.getInfo();

    if (reykValid === 0 || grindValid === 0) {
      console.log('Dataset: ' + chosen.id + ' | Band: ' + band + ' | Images: ' + chosen.size);
      console.log('Reykjavík valid pixels: ' + reykValid + '/' + reykTotal);
      console.log('Grindavík valid pixels: ' + grindValid + '/' + grindTotal);
      console.log('No valid pixels after masking.');
      console.log('C2');
      return;
    }

    if (reykMean === null || grindMean === null || !isFinite(reykMean) || !isFinite(grindMean) ||
        reykMean < 0 || grindMean < 0 || reykMean > 1e5 || grindMean > 1e5) {
      console.log('Invalid mean values.');
      console.log('Reykjavík mean: ' + reykMean + ' | Grindavík mean: ' + grindMean);
      console.log('C3');
      return;
    }

    // 4. Output concise evidence
    var reykPct = (reykValid / reykTotal) * 100.0;
    var grindPct = (grindValid / grindTotal) * 100.0;

    var dateNote = (chosen.id.indexOf('VNP46A2') !== -1) ? '2024-11-21 (daily)' : '2024-11 (monthly)';
    console.log('Date used: ' + dateNote);
    console.log('Dataset: ' + chosen.id + ' | Band: ' + band + ' | Images: ' + chosen.size);
    console.log('Reykjavík mean: ' + reykMean.toFixed(3) + ' | pixels: ' + reykValid + '/' + reykTotal + ' (' + reykPct.toFixed(1) + '%)');
    console.log('Grindavík mean: ' + grindMean.toFixed(3) + ' | pixels: ' + grindValid + '/' + grindTotal + ' (' + grindPct.toFixed(1) + '%)');
    console.log('Grindavík > Reykjavík? ' + (grindMean > reykMean));

    // 5. Final Answer
    if (grindMean > reykMean) {
      console.log('A');
    } else {
      console.log('B');
    }

  } catch (err) {
    console.log('Error: ' + String(err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

